// calendar.ax — proleptic Gregorian date arithmetic for a booking service.
//
// Dates are (year, month, day) with year >= 1, month 1..12 and a valid day.
// Weekdays are numbered ISO-style: 0 = Monday, 1 = Tuesday, ... 6 = Sunday.
//
//   axon test calendar.ax

// A year is a leap year if it is divisible by 4, except century years, which
// are leap years only when divisible by 400 (1900 is not, 2000 is).
fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: i64) -> i64 {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

// 1-based ordinal day within the year: Jan 1 = 1, Dec 31 = 365 (366 in a leap year).
fn day_of_year(y: i64, m: i64, d: i64) -> i64 {
    let n = d
    let k = 1
    while k < m {
        n = n + days_in_month(y, k)
        k = k + 1
    }
    n
}

// Signed number of days from the first date to the second (negative when the
// second date is earlier). Each date is turned into its ordinal counted from
// 0001-01-01: the days of all whole years before it (365 each, plus one per
// leap year) plus its day of the year.
fn days_between(y1: i64, m1: i64, d1: i64, y2: i64, m2: i64, d2: i64) -> i64 {
    let p1 = y1 - 1
    let a = p1 * 365 + p1 / 4 - p1 / 100 + p1 / 400 + day_of_year(y1, m1, d1)
    let p2 = y2 - 1
    let b = p2 * 365 + p2 / 4 - p2 / 100 + p2 / 400 + day_of_year(y2, m2, d2)
    b - a
}

// ISO weekday, 0 = Monday ... 6 = Sunday (Sakamoto's method; January and
// February count as months of the previous year).
fn weekday(y: i64, m: i64, d: i64) -> i64 {
    let t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    let yy = if m < 3 { y - 1 } else { y }
    let sunday_based = (yy + yy / 4 - yy / 100 + yy / 400 + t[m - 1] + d) % 7
    (sunday_based + 6) % 7
}

// Number of ISO weeks in year y: 53 when Jan 1 is a Thursday, or when y is a
// leap year and Jan 1 is a Wednesday; 52 otherwise.
fn weeks_in_year(y: i64) -> i64 {
    let jan1 = weekday(y, 1, 1)
    if jan1 == 3 || (is_leap(y) && jan1 == 2) { 53 } else { 52 }
}

// ISO 8601 week number (1..53). Weeks start on Monday and week 1 is the week
// that contains the year's first Thursday, so Jan 1-3 can belong to the last
// week of the previous year and Dec 29-31 to week 1 of the next.
fn iso_week(y: i64, m: i64, d: i64) -> i64 {
    let w = (day_of_year(y, m, d) - weekday(y, m, d) + 9) / 7
    if w < 1 {
        weeks_in_year(y - 1)
    } else if w > weeks_in_year(y) {
        1
    } else {
        w
    }
}

@[test]
fn test_leap_basic() {
    assert(is_leap(2024))
    assert(!is_leap(2023))
    assert(is_leap(1996))
}

@[test]
fn test_leap_centuries() {
    assert(!is_leap(1900))
    assert(is_leap(2000))
    assert(!is_leap(2100))
    assert(is_leap(2400))
}

@[test]
fn test_days_in_month() {
    assert_eq(days_in_month(2024, 2), 29)
    assert_eq(days_in_month(2023, 2), 28)
    assert_eq(days_in_month(2023, 4), 30)
    assert_eq(days_in_month(2023, 12), 31)
}

@[test]
fn test_day_of_year() {
    assert_eq(day_of_year(2023, 1, 1), 1)
    assert_eq(day_of_year(2023, 12, 31), 365)
    assert_eq(day_of_year(2024, 12, 31), 366)
    assert_eq(day_of_year(2024, 3, 1), 61)
}

@[test]
fn test_days_between_within_a_year() {
    assert_eq(days_between(2024, 1, 1, 2024, 3, 1), 60)
    assert_eq(days_between(2023, 1, 1, 2023, 3, 1), 59)
    assert_eq(days_between(2000, 2, 28, 2000, 3, 1), 2)
}

@[test]
fn test_days_between_across_years() {
    assert_eq(days_between(2019, 6, 15, 2024, 6, 15), 1827)
    assert_eq(days_between(1999, 12, 31, 2000, 1, 1), 1)
    assert_eq(days_between(2024, 3, 1, 2023, 3, 1), -366)
    assert_eq(days_between(2023, 11, 30, 2024, 2, 29), 91)
}

@[test]
fn test_days_between_long_spans() {
    assert_eq(days_between(1900, 1, 1, 2000, 1, 1), 36524)
    assert_eq(days_between(1970, 1, 1, 2024, 10, 12), 20008)
    assert_eq(days_between(1899, 12, 31, 1900, 3, 1), 60)
}

@[test]
fn test_weekday() {
    assert_eq(weekday(2024, 1, 15), 0)
    assert_eq(weekday(2000, 1, 1), 5)
    assert_eq(weekday(1970, 1, 1), 3)
    assert_eq(weekday(2024, 2, 29), 3)
}

@[test]
fn test_weekday_more() {
    assert_eq(weekday(1999, 12, 31), 4)
    assert_eq(weekday(2023, 3, 1), 2)
    assert_eq(weekday(2100, 3, 1), 0)
    assert_eq(weekday(1900, 2, 28), 2)
}

@[test]
fn test_iso_week_midyear() {
    assert_eq(iso_week(2024, 6, 15), 24)
    assert_eq(iso_week(2023, 10, 12), 41)
}

@[test]
fn test_iso_week_year_start() {
    assert_eq(iso_week(2021, 1, 1), 53)
    assert_eq(iso_week(2023, 1, 1), 52)
    assert_eq(iso_week(2024, 1, 1), 1)
    assert_eq(iso_week(2016, 1, 3), 53)
    assert_eq(iso_week(2027, 1, 1), 53)
}

@[test]
fn test_iso_week_year_end() {
    assert_eq(iso_week(2024, 12, 30), 1)
    assert_eq(iso_week(2026, 12, 31), 53)
    assert_eq(iso_week(2019, 12, 30), 1)
    assert_eq(iso_week(2015, 12, 31), 53)
    assert_eq(iso_week(2020, 12, 31), 53)
}

// intervals.ax — half-open time intervals for a room-booking calendar.
//
// An interval [lo, hi) contains every t with lo <= t < hi. Two intervals that
// only touch ([1, 3) and [3, 5)) share no point, so they do not overlap; they
// are, however, adjacent, and merging joins them into one block. An interval
// with lo >= hi is empty and is ignored everywhere.
//
//   axon test intervals.ax

type Iv = { lo: i64, hi: i64 }

type Ev = { t: i64, d: i64 }

// The union of `xs` as disjoint, non-adjacent intervals sorted by start.
// Overlapping or touching intervals are joined; an interval inside another
// disappears into it.
fn merge(xs: &[Iv]) -> [Iv] {
    let s = arr_sort_by(xs, |a, b| a.lo - b.lo)
    let out = []
    for i in 0..len(s) {
        let iv = s[i]
        if iv.lo < iv.hi {
            let n = len(out)
            if n > 0 && iv.lo <= out[n - 1].hi {
                if iv.hi > out[n - 1].hi {
                    out[n - 1] = Iv { lo: out[n - 1].lo, hi: iv.hi }
                }
            } else {
                out = arr_push(out, iv)
            }
        }
    }
    out
}

// Total length of time covered by at least one interval.
fn covered_length(xs: &[Iv]) -> i64 {
    let m = merge(xs)
    let total = 0
    for i in 0..len(m) {
        total = total + m[i].hi - m[i].lo
    }
    total
}

// The largest number of intervals that share a common point: how many rooms
// the bookings need at the busiest moment. A sweep over start (+1) and end
// (-1) events; at the same instant an end is processed before a start,
// because a booking ending at t frees its room for one starting at t.
fn max_overlap(xs: &[Iv]) -> i64 {
    let ev = []
    for i in 0..len(xs) {
        if xs[i].lo < xs[i].hi {
            ev = arr_push(ev, Ev { t: xs[i].lo, d: 1 })
            ev = arr_push(ev, Ev { t: xs[i].hi, d: -1 })
        }
    }
    let s = arr_sort_by(ev, |a, b| if a.t != b.t { a.t - b.t } else { a.d - b.d })
    let cur = 0
    let best = 0
    for i in 0..len(s) {
        cur = cur + s[i].d
        if cur > best {
            best = cur
        }
    }
    best
}

// The earliest start t >= from such that [t, t + dur) overlaps no interval
// in `busy`.
fn first_free(busy: &[Iv], from: i64, dur: i64) -> i64 {
    let m = merge(busy)
    let t = from
    for i in 0..len(m) {
        if m[i].hi > t && m[i].lo < t + dur {
            t = m[i].hi
        }
    }
    t
}

@[test]
fn test_merge_basic() {
    let m = merge(&[Iv { lo: 1, hi: 3 }, Iv { lo: 2, hi: 6 }, Iv { lo: 8, hi: 10 }, Iv { lo: 15, hi: 18 }])
    assert_eq(len(m), 3)
    assert_eq(m[0].lo, 1)
    assert_eq(m[0].hi, 6)
    assert_eq(m[1].lo, 8)
    assert_eq(m[2].hi, 18)
}

@[test]
fn test_merge_unsorted_and_touching() {
    let m = merge(&[Iv { lo: 5, hi: 7 }, Iv { lo: 1, hi: 3 }, Iv { lo: 3, hi: 5 }])
    assert_eq(len(m), 1)
    assert_eq(m[0].lo, 1)
    assert_eq(m[0].hi, 7)
    let n = merge(&[Iv { lo: 4, hi: 9 }, Iv { lo: 1, hi: 2 }])
    assert_eq(len(n), 2)
    assert_eq(n[0].lo, 1)
    assert_eq(n[1].lo, 4)
}

@[test]
fn test_merge_contained_and_empty() {
    let m = merge(&[Iv { lo: 1, hi: 10 }, Iv { lo: 2, hi: 3 }, Iv { lo: 4, hi: 5 }])
    assert_eq(len(m), 1)
    assert_eq(m[0].hi, 10)
    let e = merge(&[Iv { lo: 3, hi: 3 }, Iv { lo: 5, hi: 4 }])
    assert_eq(len(e), 0)
}

@[test]
fn test_covered_length() {
    assert_eq(covered_length(&[Iv { lo: 1, hi: 3 }, Iv { lo: 2, hi: 6 }, Iv { lo: 8, hi: 10 }]), 7)
    assert_eq(covered_length(&[Iv { lo: 0, hi: 5 }, Iv { lo: 5, hi: 9 }]), 9)
    assert_eq(covered_length(&[Iv { lo: 2, hi: 12 }, Iv { lo: 4, hi: 6 }]), 10)
}

@[test]
fn test_max_overlap_nested() {
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 10 }, Iv { lo: 1, hi: 2 }, Iv { lo: 3, hi: 4 }]), 2)
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 10 }, Iv { lo: 1, hi: 9 }, Iv { lo: 2, hi: 8 }]), 3)
}

@[test]
fn test_max_overlap_touching() {
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 5 }, Iv { lo: 5, hi: 9 }]), 1)
    assert_eq(max_overlap(&[Iv { lo: 1, hi: 3 }, Iv { lo: 3, hi: 4 }, Iv { lo: 4, hi: 6 }]), 1)
}

@[test]
fn test_max_overlap_meetings() {
    let day = [Iv { lo: 9, hi: 10 }, Iv { lo: 9, hi: 12 }, Iv { lo: 11, hi: 13 }, Iv { lo: 10, hi: 11 }, Iv { lo: 12, hi: 14 }, Iv { lo: 9, hi: 14 }]
    assert_eq(max_overlap(&day), 3)
    assert_eq(max_overlap(&[Iv { lo: 1, hi: 4 }, Iv { lo: 2, hi: 3 }, Iv { lo: 5, hi: 8 }, Iv { lo: 6, hi: 7 }]), 2)
}

@[test]
fn test_first_free() {
    let busy = [Iv { lo: 9, hi: 10 }, Iv { lo: 10, hi: 12 }, Iv { lo: 13, hi: 15 }]
    assert_eq(first_free(&busy, 9, 1), 12)
    assert_eq(first_free(&busy, 9, 2), 15)
    assert_eq(first_free(&busy, 8, 1), 8)
    assert_eq(first_free(&busy, 12, 1), 12)
}

// textproc.ax — small text utilities for an import pipeline: CSV fields,
// greedy word wrapping for a fixed-width terminal, and card-number checks.
//
//   axon test textproc.ax

// Number of fields in one CSV line. Fields are separated by commas; a field
// may be wrapped in double quotes, and inside quotes a comma is data, not a
// separator. An empty line is one empty field.
fn csv_field_count(line: str) -> i64 {
    let n = len(line)
    let fields = 1
    let in_q = false
    let i = 0
    while i < n {
        let c = char_at(line, i)
        if c == 34 {
            in_q = !in_q
        } else if c == 44 && !in_q {
            fields = fields + 1
        }
        i = i + 1
    }
    fields
}

// The k-th field (0-based) of one CSV line, unquoted: surrounding double
// quotes are removed, a comma inside quotes is kept, and a doubled quote ("")
// inside a quoted field stands for one literal quote. Out of range: "".
fn csv_field(line: str, k: i64) -> str {
    let n = len(line)
    let idx = 0
    let cur = ""
    let in_q = false
    let i = 0
    while i < n {
        let c = char_at(line, i)
        if in_q {
            if c == 34 {
                if i + 1 < n && char_at(line, i + 1) == 34 {
                    cur = cur + "\""
                    i = i + 1
                } else {
                    in_q = false
                }
            } else {
                cur = cur + str_slice(line, i, i + 1)
            }
        } else if c == 34 {
            in_q = true
        } else if c == 44 {
            if idx == k {
                return cur
            }
            idx = idx + 1
            cur = ""
        } else {
            cur = cur + str_slice(line, i, i + 1)
        }
        i = i + 1
    }
    if idx == k { cur } else { "" }
}

// How many lines greedy word wrapping produces. Words are separated by one or
// more spaces; a line holds as many whole words as fit, joined by single
// spaces, within `width` characters. A word longer than `width` is never
// split: it sits on a line of its own. Text with no words takes 0 lines.
fn word_wrap_lines(text: str, width: i64) -> i64 {
    let lines = 0
    let cur = 0
    let n = len(text)
    let i = 0
    while i < n {
        if char_at(text, i) == 32 {
            i = i + 1
        } else {
            let j = i
            while j < n && char_at(text, j) != 32 {
                j = j + 1
            }
            let w = j - i
            if cur == 0 {
                lines = lines + 1
                cur = w
            } else if cur + 1 + w <= width {
                cur = cur + 1 + w
            } else {
                lines = lines + 1
                cur = w
            }
            i = j
        }
    }
    lines
}

// Luhn checksum (card and account numbers). Spaces are ignored; any other
// non-digit makes the number invalid, as does having fewer than two digits.
// Starting from the RIGHTMOST digit, every second digit is doubled (9 is
// subtracted when the double exceeds 9); the number is valid iff the sum of
// all digits is a multiple of 10.
fn luhn_valid(s: str) -> bool {
    let sum = 0
    let count = 0
    let ok = true
    let i = len(s) - 1
    while i >= 0 {
        let c = char_at(s, i)
        if c >= 48 && c <= 57 {
            let d = c - 48
            if count % 2 == 1 {
                d = d * 2
                if d > 9 {
                    d = d - 9
                }
            }
            sum = sum + d
            count = count + 1
        } else if c != 32 {
            ok = false
        }
        i = i - 1
    }
    ok && count >= 2 && sum % 10 == 0
}

@[test]
fn test_csv_field_count_plain() {
    assert_eq(csv_field_count("a,b,c"), 3)
    assert_eq(csv_field_count(""), 1)
    assert_eq(csv_field_count("a,,c,"), 4)
}

@[test]
fn test_csv_field_count_quoted() {
    assert_eq(csv_field_count("\"Smith, John\",42,\"NY\""), 3)
    assert_eq(csv_field_count("\"a,b,c\""), 1)
}

@[test]
fn test_csv_field_plain() {
    assert(csv_field("id,name,city", 0) == "id")
    assert(csv_field("id,name,city", 2) == "city")
    assert(csv_field("id,name,city", 3) == "")
    assert(csv_field("a,,c", 1) == "")
}

@[test]
fn test_csv_field_quoted_commas() {
    assert(csv_field("\"Smith, John\",42,\"New York, NY\"", 0) == "Smith, John")
    assert(csv_field("\"Smith, John\",42,\"New York, NY\"", 1) == "42")
    assert(csv_field("\"Smith, John\",42,\"New York, NY\"", 2) == "New York, NY")
    assert(csv_field("x,\"1,2,3\",y", 2) == "y")
}

@[test]
fn test_csv_field_escaped_quotes() {
    assert(csv_field("\"say \"\"hi\"\"\",ok", 0) == "say \"hi\"")
    assert(csv_field("\"say \"\"hi\"\"\",ok", 1) == "ok")
    assert(csv_field("7,\"a \"\"b\"\", c\",8", 1) == "a \"b\", c")
    assert(csv_field("7,\"a \"\"b\"\", c\",8", 2) == "8")
}

@[test]
fn test_word_wrap_simple() {
    assert_eq(word_wrap_lines("hello world", 11), 1)
    assert_eq(word_wrap_lines("hello world", 10), 2)
    assert_eq(word_wrap_lines("", 5), 0)
    assert_eq(word_wrap_lines("   ", 5), 0)
}

@[test]
fn test_word_wrap_word_boundaries() {
    assert_eq(word_wrap_lines("aaaa bbbb cccc", 4), 3)
    assert_eq(word_wrap_lines("ab cd ef gh", 5), 2)
    assert_eq(word_wrap_lines("the quick brown fox jumps over the lazy dog", 10), 5)
    assert_eq(word_wrap_lines("one  two   three", 9), 2)
}

@[test]
fn test_word_wrap_long_words() {
    assert_eq(word_wrap_lines("supercalifragilistic is long", 8), 2)
    assert_eq(word_wrap_lines("a bbbbbbbbbbbb c", 4), 3)
    assert_eq(word_wrap_lines("xxxxxxxxxx", 3), 1)
}

@[test]
fn test_luhn_card_numbers() {
    assert(luhn_valid("4539 1488 0343 6467"))
    assert(!luhn_valid("8273 1232 7352 0569"))
    assert(luhn_valid("4111 1111 1111 1111"))
}

@[test]
fn test_luhn_odd_length() {
    assert(luhn_valid("79927398713"))
    assert(!luhn_valid("79927398710"))
    assert(luhn_valid("059"))
}

@[test]
fn test_luhn_amex() {
    assert(luhn_valid("378282246310005"))
    assert(!luhn_valid("378282246310006"))
    assert(luhn_valid("12345678903"))
}

@[test]
fn test_luhn_rejects_junk() {
    assert(!luhn_valid("0"))
    assert(!luhn_valid("4111-1111-1111-1111"))
    assert(!luhn_valid(""))
}

// sequences.ax — dynamic-programming helpers for a diff/merge tool and a
// vending-machine change module.
//
//   axon test sequences.ax

// Edit distance: the minimum number of single-character insertions,
// deletions and substitutions that turn `a` into `b`.
fn levenshtein(a: str, b: str) -> i64 {
    let n = len(a)
    let m = len(b)
    let prev = []
    for j in 0..m + 1 {
        prev = arr_push(prev, j)
    }
    for i in 1..n + 1 {
        let cur = arr_push([], i)
        for j in 1..m + 1 {
            let cost = if char_at(a, i - 1) == char_at(b, j - 1) { 0 } else { 1 }
            let best = min_i64(prev[j] + 1, cur[j - 1] + 1)
            cur = arr_push(cur, min_i64(best, prev[j - 1] + cost))
        }
        prev = cur
    }
    prev[m]
}

// Length of the longest common subsequence of `a` and `b` (characters in the
// same order, not necessarily adjacent).
fn lcs_len(a: str, b: str) -> i64 {
    let n = len(a)
    let m = len(b)
    let prev = []
    for j in 0..m + 1 {
        prev = arr_push(prev, 0)
    }
    for i in 1..n + 1 {
        let cur = arr_push([], 0)
        for j in 1..m + 1 {
            if char_at(a, i - 1) == char_at(b, j - 1) {
                cur = arr_push(cur, prev[j - 1] + 1)
            } else {
                cur = arr_push(cur, max_i64(prev[j], cur[j - 1]))
            }
        }
        prev = cur
    }
    prev[m]
}

// Length of the longest strictly increasing subsequence of `xs` (elements in
// order, not necessarily adjacent).
fn lis_len(xs: &[i64]) -> i64 {
    let n = len(xs)
    let best = []
    let answer = 0
    for i in 0..n {
        let b = 1
        for j in 0..i {
            if xs[j] < xs[i] && best[j] + 1 > b {
                b = best[j] + 1
            }
        }
        best = arr_push(best, b)
        if b > answer {
            answer = b
        }
    }
    answer
}

// Fewest coins (unlimited supply of each denomination in `coins`) that add up
// to exactly `amount`, or -1 if no combination does. 0 for amount 0.
fn min_coins(coins: &[i64], amount: i64) -> i64 {
    let none = amount + 1
    let best = arr_push([], 0)
    for v in 1..amount + 1 {
        let b = none
        for k in 0..len(coins) {
            let c = coins[k]
            if c <= v && best[v - c] + 1 < b {
                b = best[v - c] + 1
            }
        }
        best = arr_push(best, b)
    }
    if best[amount] >= none { -1 } else { best[amount] }
}

// Number of different multisets of coins from `coins` (unlimited supply)
// that add up to `amount`. Order does not matter: 1+2 and 2+1 are the same
// way. There is exactly one way to make 0 (no coins).
fn count_ways(coins: &[i64], amount: i64) -> i64 {
    let ways = arr_push([], 1)
    for v in 1..amount + 1 {
        ways = arr_push(ways, 0)
    }
    for k in 0..len(coins) {
        let c = coins[k]
        for v in c..amount + 1 {
            ways[v] = ways[v] + ways[v - c]
        }
    }
    ways[amount]
}

@[test]
fn test_levenshtein_basics() {
    assert_eq(levenshtein("kitten", "sitting"), 3)
    assert_eq(levenshtein("", "abc"), 3)
    assert_eq(levenshtein("same", "same"), 0)
    assert_eq(levenshtein("book", "back"), 2)
}

@[test]
fn test_levenshtein_flaw_lawn() {
    assert_eq(levenshtein("flaw", "lawn"), 2)
}

@[test]
fn test_levenshtein_shifted() {
    assert_eq(levenshtein("abc", "bc"), 1)
    assert_eq(levenshtein("sunday", "saturday"), 3)
    assert_eq(levenshtein("abcdef", "azced"), 3)
}

@[test]
fn test_lcs_identical_and_disjoint() {
    assert_eq(lcs_len("abc", "abc"), 3)
    assert_eq(lcs_len("abc", "def"), 0)
    assert_eq(lcs_len("", "x"), 0)
    assert_eq(lcs_len("axbycz", "abc"), 3)
}

@[test]
fn test_lcs_classic() {
