// Tier-1 stdlib: array utilities (read-only aggregation + selection).
//
// Arrays became first-class once `len` accepted slices; these are the
// aggregation/selection helpers agent code needs over a candidate set — in
// particular `argmax`, the core decision primitive: pick the best-scoring
// option from N. Arrays are immutable here — Axon has no `xs[i] = v` place
// assignment yet, so you mutate by building a new array / rebinding, and every
// helper below is a pure fold.
//
//   axon test examples/stdlib/arrays.ax
//   axon run  examples/stdlib/arrays.ax

fn sum(xs: [i64]) -> i64 {
    let t = 0
    for i in 0..len(xs) { t = t + xs[i] }
    t
}

fn max_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] > m { m = xs[i] } }
    m
}

fn min_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] < m { m = xs[i] } }
    m
}

// Index of the largest element — the "pick the best candidate" primitive.
// Ties resolve to the first (lowest index).
fn argmax(xs: [i64]) -> i64 {
    let best = 0
    for i in 0..len(xs) { if xs[i] > xs[best] { best = i } }
    best
}

fn contains(xs: [i64], target: i64) -> bool {
    let found = false
    for i in 0..len(xs) { if xs[i] == target { found = true } }
    found
}

// How many elements are >= threshold (a simple count-where).
fn count_at_least(xs: [i64], threshold: i64) -> i64 {
    let n = 0
    for i in 0..len(xs) { if xs[i] >= threshold { n = n + 1 } }
    n
}

@[test]
fn test_sum() { assert_eq(sum([10, 20, 30]), 60) }

@[test]
fn test_max_min() {
    assert_eq(max_of([3, 9, 2, 7]), 9)
    assert_eq(min_of([3, 9, 2, 7]), 2)
}

@[test]
fn test_argmax_picks_best() {
    assert_eq(argmax([10, 50, 30]), 1) // index of 50
    assert_eq(argmax([5, 5, 5]), 0)    // ties resolve to the first
}

@[test]
fn test_contains() {
    assert(contains([1, 2, 3], 2))
    assert(!contains([1, 2, 3], 9))
}

@[test]
fn test_count_at_least() {
    assert_eq(count_at_least([10, 40, 70, 90], 50), 2)
}

fn main() {
    // An agent scoring candidate actions and choosing the best.
    let scores = [42, 88, 17, 90, 63]
    let best = argmax(scores)
    let bs = scores[best]
    println("candidates: 5, best index {to_str(best)} (score {to_str(bs)})")
    println("total score {to_str(sum(scores))}, how many >= 60: {to_str(count_at_least(scores, 60))}")
}

@[test]
fn test_argmax_prefers_latest_tie() {
    assert_eq(argmax([5, 5, 5]), 2)
}

// scorelib.ax — an importable Axon library (no `main`, so it can be `use`d).
//
// Demonstrates that Axon programs are modular: another file declares
// `mod scorelib` + `use scorelib.{…}` and the module is resolved from
// AXON_PATH at compile time, then run by the interpreter. See agent.ax.
//
//   axon test examples/modular/scorelib.ax     # the @[test]s below

// Weighted blend of a quality score and a confidence percentage (0..100).
fn weighted(quality: i64, qw: i64, confidence_pct: i64, cw: i64) -> i64 {
    (quality * qw + confidence_pct * cw) / max_i64(qw + cw, 1)
}

// Approve iff the combined score clears the floor.
fn approve(combined: i64, floor: i64) -> bool {
    combined >= floor
}

@[test]
fn test_weighted() {
    // (90*6 + 80*4) / 10 = 86
    assert_eq(weighted(90, 6, 80, 4), 86)
}

@[test]
fn test_approve() {
    assert(approve(86, 70))
    assert(!approve(60, 70))
}

@[test]
fn test_weighted_rounds_up() {
    assert_eq(weighted(90, 6, 80, 4), 87)
}

// Tier-1 stdlib: Uncertain combinators — reasoning under calibrated confidence.
//
// Axon's Uncertain<T> carries a value plus a self-reported confidence in
// [0,1]. The runtime constructs them (uncertain_new, ai_extract_uncertain_*);
// these helpers COMBINE them, so goal/agent code can reason about how sure it
// is, not just what it computed.
//
//   axon test examples/stdlib/uncertain.ax
//   axon run  examples/stdlib/uncertain.ax

fn u_i64(value: i64, confidence: f64) -> Uncertain<i64> {
    uncertain_new(value, confidence)
}

fn u_val(u: Uncertain<i64>) -> i64 {
    u.value
}

fn u_conf(u: Uncertain<i64>) -> f64 {
    u.confidence
}

// Does this estimate clear a confidence bar?
fn u_confident(u: Uncertain<i64>, threshold: f64) -> bool {
    u.confidence >= threshold
}

// Joint confidence of two independent estimates (probabilistic AND).
fn u_and(a: Uncertain<i64>, b: Uncertain<i64>) -> f64 {
    a.confidence * b.confidence
}

// Confidence that at least one holds (probabilistic OR, independence).
fn u_or(a: Uncertain<i64>, b: Uncertain<i64>) -> f64 {
    a.confidence + b.confidence - a.confidence * b.confidence
}

// Pick the more-confident of two estimates.
fn u_max_conf(a: Uncertain<i64>, b: Uncertain<i64>) -> Uncertain<i64> {
    if a.confidence >= b.confidence { a } else { b }
}

@[test]
fn test_u_accessors() {
    let u = u_i64(42, 0.9)
    assert_eq(u_val(u), 42)
    assert_eq_f64(u_conf(u), 0.9)
}

@[test]
fn test_u_confident() {
    let u = u_i64(5, 0.9)
    assert(u_confident(u, 0.8))
    assert(!u_confident(u, 0.95))
}

@[test]
fn test_u_and() {
    assert_eq_f64(u_and(u_i64(1, 0.5), u_i64(1, 0.8)), 0.4)
}

@[test]
fn test_u_or() {
    // 0.5 + 0.8 - 0.4 = 0.9
    assert_eq_f64(u_or(u_i64(1, 0.5), u_i64(1, 0.8)), 0.9)
}

@[test]
fn test_u_max_conf() {
    let m = u_max_conf(u_i64(1, 0.3), u_i64(2, 0.7))
    assert_eq(u_val(m), 2)
    assert_eq_f64(u_conf(m), 0.7)
}

fn main() {
    let a = u_i64(1, 0.7)
    let b = u_i64(1, 0.85)
    println("a: value {to_str(u_val(a))} conf {to_str_f64(u_conf(a))}")
    println("joint confidence (both agree): {to_str_f64(u_and(a, b))}")
    println("either holds: {to_str_f64(u_or(a, b))}")
    let best = u_max_conf(a, b)
    println("more confident estimate: value {to_str(u_val(best))} conf {to_str_f64(u_conf(best))}")
}

@[test]
fn test_u_or_adds_confidences() {
    assert_eq_f64(u_or(u_i64(1, 0.5), u_i64(1, 0.8)), 1.3)
}

